-- Per-plane catalogs allow test mappings to evolve without changing production.
CREATE TABLE waveform_voice_profiles (
 plane_id uuid NOT NULL REFERENCES waveform_environments(id) ON DELETE CASCADE,
 id text NOT NULL CHECK (id ~ '^[a-z0-9-]{1,64}$'),
 profile jsonb NOT NULL,
 PRIMARY KEY (plane_id,id),
 CHECK (profile->>'id' = id),
 CHECK (profile ?& ARRAY['id','name','description','revision','auditioned','gemini_voice','openai_voice','elevenlabs'])
);
