ALTER TABLE waveform_provider_defaults ADD COLUMN voice_profile text NOT NULL DEFAULT 'kore';
ALTER TABLE waveform_provider_defaults ADD FOREIGN KEY(plane_id,voice_profile) REFERENCES waveform_voice_profiles(plane_id,id);
ALTER TABLE waveform_account_preferences ADD COLUMN voice_profile text;
ALTER TABLE waveform_account_preferences ADD FOREIGN KEY(plane_id,voice_profile) REFERENCES waveform_voice_profiles(plane_id,id);
UPDATE waveform_account_preferences p SET voice_profile=d.voice_profile FROM waveform_provider_defaults d WHERE p.plane_id=d.plane_id;
ALTER TABLE waveform_jobs ADD COLUMN voice_profile jsonb;

-- A catalog edit creates a new mapping revision for subsequent generations.
CREATE FUNCTION waveform_voice_profile_revision() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NEW.profile IS DISTINCT FROM OLD.profile THEN
  NEW.profile = jsonb_set(NEW.profile, '{revision}', to_jsonb((OLD.profile->>'revision')::integer + 1));
 END IF;
 RETURN NEW;
END;
$$;
CREATE TRIGGER waveform_voice_profile_revision BEFORE UPDATE OF profile ON waveform_voice_profiles
FOR EACH ROW EXECUTE FUNCTION waveform_voice_profile_revision();
